/**
 * Proves the FSRS-6 code INLINED INTO AEGIS index.html is bit-for-bit faithful
 * to the reference implementation — not a hand-retyped drift.
 *
 * The vectors in fsrs6-oracle.json were generated by py-fsrs 6.3.2
 * (open-spaced-repetition), NOT by ARC and NOT by AEGIS. Any disagreement is
 * an AEGIS defect.
 *
 * The module under test is sliced straight out of index.html by extract.sh —
 * nothing is retyped here.
 */
import * as A from '/tmp/fsrs-inline.mjs';
import { readFileSync } from 'node:fs';

const O = JSON.parse(readFileSync('/home/claude/arc-v4.3.0/conformance/fsrs6-oracle.json', 'utf8'));
const EPS = 1e-9;
let pass = 0, fail = 0;
const fails = [];

function eq(name, got, want, eps = EPS) {
  const ok = Math.abs(got - want) <= eps * Math.max(1, Math.abs(want));
  if (ok) pass++; else { fail++; fails.push(`${name}: got ${got}, oracle ${want}`); }
}

// --- constants -------------------------------------------------------------
eq('parameters.length', A.FSRS_W.length, 21, 0);
O.parameters.forEach((w, i) => eq(`w[${i}]`, A.FSRS_W[i], w, 0));
eq('decay', A.FSRS_DECAY, O.decay);
eq('factor', A.FSRS_FACTOR, O.factor);

// --- per-function vectors --------------------------------------------------
O.initial_stability.forEach(v => eq(`S0(${v.rating})`, A.fsrsInitialStability(v.rating), v.expect));
O.initial_difficulty.forEach(v => eq(`D0(${v.rating})`, A.fsrsInitialDifficulty(v.rating), v.expect));
O.next_difficulty.forEach(v => eq(`D(${v.difficulty},${v.rating})`, A.fsrsNextDifficulty(v.difficulty, v.rating), v.expect));
O.retrievability.forEach(v => eq(`R(${v.elapsed_days},${v.stability})`, A.fsrsRetrievability(v.elapsed_days, v.stability), v.expect));
O.recall_stability.forEach(v => eq(`Srecall(${v.difficulty},${v.stability},${v.retrievability},${v.rating})`,
  A.fsrsNextRecallStability(v.difficulty, v.stability, v.retrievability, v.rating), v.expect));
O.forget_stability.forEach(v => eq(`Sforget(${v.difficulty},${v.stability},${v.retrievability})`,
  A.fsrsNextForgetStability(v.difficulty, v.stability, v.retrievability), v.expect));
O.short_term_stability.forEach(v => eq(`Sshort(${v.stability},${v.rating})`,
  A.fsrsShortTermStability(v.stability, v.rating), v.expect));
O.next_interval.forEach(v => eq(`I(S=${v.stability},DR=${v.desired_retention})`, A.fsrsNextInterval(v.stability, v.desired_retention), v.expect, 0));

// --- full sequences, driven through the AEGIS adapter ----------------------
// This is the real test: it exercises fsrsNew/fsrsReview end to end, including
// the elapsed-days arithmetic and the new/review/lapse branch selection.
const DAY = 86400000;
for (const seq of O.sequences) {
  let now = new Date('2026-01-01T00:00:00.000Z');
  const card = A.fsrsNew(now);
  seq.steps.forEach((step, n) => {
    A.fsrsReview(card, step.rating, now);
    eq(`seq[${seq.id}].${n}.stability`, card.stability, step.stability);
    eq(`seq[${seq.id}].${n}.difficulty`, card.difficulty, step.difficulty);
    const interval = Math.round((Date.parse(card.due) - now.getTime()) / DAY);
    eq(`seq[${seq.id}].${n}.interval_days`, interval, step.interval_days, 0);
    now = new Date(now.getTime() + step.interval_days * DAY); // review exactly when due
  });
}

// --- adapter behaviour the oracle does not cover ---------------------------
function assert(name, cond) { if (cond) pass++; else { fail++; fails.push(name); } }

// Lapse path: Again must shorten AND record a lapse. This is the 1.4.0 bug.
{
  const t0 = new Date('2026-01-01T00:00:00.000Z');
  const good = A.fsrsNew(t0);
  A.fsrsReview(good, 3, t0);                                   // establish
  let t = new Date(t0.getTime() + 2 * DAY);
  A.fsrsReview(good, 3, t); const longS = good.stability;
  const longI = Math.round((Date.parse(good.due) - t.getTime()) / DAY);

  const bad = A.fsrsNew(t0);
  A.fsrsReview(bad, 3, t0);
  A.fsrsReview(bad, 1, t);  const shortI = Math.round((Date.parse(bad.due) - t.getTime()) / DAY);

  assert('Again shortens vs Good', shortI < longI);
  assert('Again drops stability', bad.stability < longS);
  assert('Again increments lapses', bad.lapses === 1);
  assert('Good leaves lapses at 0', good.lapses === 0);
  assert('Again sets state=relearning', bad.state === 'relearning');
  assert('reps counted', good.reps === 2 && bad.reps === 2);
}

// A first-ever Again is not a lapse (no memory existed to lose).
{
  const t0 = new Date('2026-01-01T00:00:00.000Z');
  const c = A.fsrsNew(t0);
  assert('new card starts with null stability', c.stability === null && c.state === 'new');
  A.fsrsReview(c, 1, t0);
  assert('first-review Again is not a lapse', c.lapses === 0);
  assert('first-review Again still schedules', Date.parse(c.due) > t0.getTime());
}

// Monotonicity: harder grade never schedules further out than an easier one.
{
  const t0 = new Date('2026-01-01T00:00:00.000Z');
  const t1 = new Date(t0.getTime() + 10 * DAY);
  const iv = [1, 2, 3, 4].map(g => {
    const c = A.fsrsNew(t0); A.fsrsReview(c, 3, t0); A.fsrsReview(c, g, t1);
    return Math.round((Date.parse(c.due) - t1.getTime()) / DAY);
  });
  assert(`grade monotonicity ${JSON.stringify(iv)}`, iv[0] <= iv[1] && iv[1] <= iv[2] && iv[2] <= iv[3]);
}

// Determinism: same card + same grade + same clock → identical result.
{
  const t0 = new Date('2026-01-01T00:00:00.000Z');
  const t1 = new Date(t0.getTime() + 5 * DAY);
  const run = () => { const c = A.fsrsNew(t0); A.fsrsReview(c, 3, t0); A.fsrsReview(c, 2, t1); return JSON.stringify(c); };
  assert('deterministic', run() === run());
}

// Banker's rounding — the divergence that half-up would introduce.
assert('roundHalfToEven(2.5)===2', A.roundHalfToEven(2.5) === 2);
assert('roundHalfToEven(3.5)===4', A.roundHalfToEven(3.5) === 4);
assert('roundHalfToEven(2.6)===3', A.roundHalfToEven(2.6) === 3);

console.log(`\nAEGIS inline FSRS-6 vs py-fsrs 6.3.2 oracle`);
console.log('─'.repeat(52));
console.log(`  ${pass} assertions passed, ${fail} failed`);
if (fail) { fails.forEach(f => console.log('  ✗ ' + f)); process.exit(1); }
console.log('  PASS — the inlined copy matches the reference exactly.\n');
